"use client";

import { useState } from "react";
import { supabase } from "@/lib/supabaseClient";
import { useRouter } from "next/navigation";
import { Dumbbell } from "lucide-react";

export default function Login() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleAuth = async (mode: "login" | "signup", e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg("");

    const { error } =
      mode === "signup"
        ? await supabase.auth.signUp({ email, password })
        : await supabase.auth.signInWithPassword({ email, password });

    if (error) {
      setErrorMsg(error.message);
      setLoading(false);
    } else {
      router.push("/");
    }
  };

  return (
    <div className="min-h-screen bg-background flex flex-col items-center justify-center p-6 pb-24">
      <div className="mb-10 text-center animate-in fade-in slide-in-from-bottom-5 duration-700">
        <h1 className="text-4xl font-black uppercase tracking-widest text-primary flex items-center justify-center gap-3">
          75 <Dumbbell className="w-8 h-8" /> Hard
        </h1>
        <p className="text-gray-500 font-semibold tracking-widest uppercase text-xs mt-2">
          Strict Accountability Tracker
        </p>
      </div>

      <div className="w-full max-w-sm bg-dark-panel p-8 rounded-3xl border border-border shadow-2xl animate-in fade-in zoom-in-95 duration-500 delay-150">
        <h2 className="text-white text-xl font-bold mb-6 text-center tracking-wide">
          ACCESS HUB
        </h2>
        
        {errorMsg && (
          <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-xl text-red-500 text-sm font-semibold text-center">
            {errorMsg}
          </div>
        )}

        <form className="flex flex-col gap-5">
          <div>
            <label className="block text-xs uppercase tracking-widest font-bold text-gray-500 mb-2">
              Email
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-background border border-border rounded-xl p-4 text-white focus:outline-none focus:border-primary transition"
              placeholder="you@example.com"
              required
            />
          </div>
          <div>
            <label className="block text-xs uppercase tracking-widest font-bold text-gray-500 mb-2">
              Password
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-background border border-border rounded-xl p-4 text-white focus:outline-none focus:border-primary transition"
              placeholder="••••••••"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-3 mt-4">
            <button
              onClick={(e) => handleAuth("login", e)}
              disabled={loading}
              className="py-4 rounded-xl bg-primary text-white font-black uppercase tracking-widest hover:bg-primary-hover transition text-sm flex items-center justify-center"
            >
              {loading ? <Dumbbell className="w-5 h-5 animate-spin" /> : "Log In"}
            </button>
            <button
              type="button"
              onClick={() => router.push("/signup")}
              disabled={loading}
              className="py-4 rounded-xl bg-background border border-border text-gray-400 font-black uppercase tracking-widest hover:bg-dark-panel hover:text-white transition text-sm flex items-center justify-center"
            >
              Sign Up
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
